python3 -I - "$P" "$FX" <<'EOF'
import json,sys,hashlib,os
P,FX=sys.argv[1:]
c=json.load(open(P+'/templates/template-contract.json'))
names=set()
def walk(o):
    if isinstance(o,dict):
        for k,v in o.items():
            if isinstance(v,str) and (v.endswith('.md') or v.endswith('.json')): names.add(v)
            walk(v)
    elif isinstance(o,list):
        for v in o:
            if isinstance(v,str) and (v.endswith('.md') or v.endswith('.json')): names.add(v)
            else: walk(v)
walk(c)
print('contract-referenced:',sorted(names))
allp=set(os.listdir(P+'/templates'))
print('in contract not in plugin dir:',sorted(n for n in names if os.path.basename(n) not in allp))
h=lambda p: hashlib.sha256(open(p,'rb').read()).hexdigest()
miss=[];diff=[];same=0
for n in sorted(allp|{os.path.basename(x) for x in names}):
    lp=FX+'/.dev-graph/templates/'+n
    if not os.path.exists(lp): miss.append(n);continue
    pp=P+'/templates/'+n
    if os.path.exists(pp):
        if h(pp)==h(lp): same+=1
        else: diff.append((n,h(pp),h(lp)))
print('missing',miss,'same',same,'diff',diff)
print('local extras',sorted(set(os.listdir(FX+'/.dev-graph/templates'))-allp))
EOF
echo "== validator"; python3 $P/scripts/validate-graph-schema.py --graph $FX/.dev-graph/state/graph.json --repo-root $FX; echo EXIT=$?
